## implement a leading-edge throttle with cancellation

```ts
function throttle<t extends unknown[]>(fn: (...args: t) => void, wait: number) {
  let last = -infinity;
  const run = (...args: t) => {
    const now = performance.now();
    if (now - last >= wait) {
      last = now;
      fn(...args);
    }
  };
  run.cancel = () => {
    last = -infinity;
  };
  return run;
}
```

